62	function validateThresholds(thresholds, evaluations) {
63	  if (!thresholds || Object.keys(thresholds).length === 0) {
64	    return { valid: true, errors: [], thresholdResults: [] };
65	  }
66	
67	  const errors = [];
68	  const metricIds = evaluations.map((m) => m.id);
