import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function validateThresholds(thresholds, evaluations) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { valid: true, errors: [], thresholdResults: [] };
  }

  const errors = [];
  const metricIds = evaluations.map((m) => m.id);

  for (const [metricId, minValue] of Object.entries(thresholds)) {
    if (!metricIds.includes(metricId)) {
      errors.push({
        type: 'unknown_metric',
        message: `Unknown metric: ${metricId}. Valid metrics: ${metricIds.join(', ')}`
      });
    } else if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
      errors.push({
        type: 'invalid_threshold',
        message: `Invalid threshold for ${metricId}: ${minValue}. Must be a number between 0 and 1`
      });
    }
  }

  if (errors.length > 0) {
    return { valid: false, errors, thresholdResults: [] };
  }

  const thresholdResults = Object.entries(thresholds).map(([metricId, minValue]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric.score;
    const passed = score !== null && score >= minValue;
    return { metric: metricId, min: minValue, score, passed };
  });

  return { valid: true, errors: [], thresholdResults };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdValidation = validateThresholds(thresholds, evaluations);
    if (!thresholdValidation.valid) {
      report._thresholdValidationError = thresholdValidation;
    } else {
      const allPassed = thresholdValidation.thresholdResults.every((r) => r.passed);
      report.passed = allPassed;
      report.thresholds = thresholdValidation.thresholdResults;
    }
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

