function parseThresholds(thresholdStrings?: string[]): { 
  thresholds: Record<string, number> | null;
  errors: string[];
} {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: null, errors: [] };
  }

  const thresholds: Record<string, number> = {};
  const errors: string[] = [];

  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
    if (!match) {
      errors.push(`Invalid threshold format: "${str}". Expected: metric=value (e.g., exact_match=0.8)`);
      continue;
    }

    const [, metric, valueStr] = match;
    const value = parseFloat(valueStr);

    if (isNaN(value) || value < 0 || value > 1) {
      errors.push(`Invalid threshold value for ${metric}: ${valueStr}. Must be between 0 and 1.`);
      continue;
    }

    if (metric in thresholds) {
      errors.push(`Duplicate threshold for metric: ${metric}. Each metric can only have one threshold.`);
      continue;
    }

    thresholds[metric] = value;
  }

  return { 
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : null,
    errors 
  };
}
