      }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeNull();
  });

  it('detects unknown metrics in thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        unknown_metric: 0.5
      }
    });
    expect(report._thresholdValidationError).toBeDefined();
    expect(report._thresholdValidationError.errors[0].type).toBe('unknown_metric');
  });

  it('detects invalid threshold values', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
