function parseThresholds(thresholdStrings?: string[]): Record<string, number> | undefined {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  const thresholds: Record<string, number> = {};
  for (const thresholdStr of thresholdStrings) {
    const parts = thresholdStr.split('=');
    if (parts.length !== 2) {
      throw new Error(`Invalid threshold format: "${thresholdStr}". Expected format: metric=value (e.g., exact_match=0.9)`);
    }
    const [metricId, valueStr] = parts;
    const value = Number.parseFloat(valueStr);
    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: "${valueStr}". Must be a number between 0 and 1.`);
    }
    thresholds[metricId] = value;
  }
  return thresholds;

